public class magic_squre_odd {
       static int[][]  matrix;
       static int   n;
       public static void magic_squre_odd_generate()
       { matrix = new int[n][n];
         //所有的数初始化为0

         matrix[0][(n-1)/2] = 1;
         int x = 0,y = (n-1)/2;

         //count:记住已经插入过的数
          for(int count = 2; count<=n*n;count++)
          while(true)
          {
          //先x-1 y+1
        	  x--;
        	  y++;

        	  //判断是否可以插入
          	  while(true)
                 {//循环判断是否越界，直到一个地方不越界为止
                    //判断是否越界：
                    //越上界x<0，则移到最下方x=x+n，y不变; continue
                   if(x<0)
                   {
                   	x += n;
                   	continue;
                   }

                   //越右界y>=n，则y=y-n，x不变;continue
                   if(y>=n)
                   {
                   	y -= n;
                   	continue;
                   }

        	    //循环判断是否该位置已经有数据，直到找到一个空位
                      //如果有数据，则移到x = x + 2;y = y - 1; continue
                   if (y<0){y+=n;continue;}
                   if(matrix[x][y] != 0 )
                   {
                   	x += 2;y -= 1;
                   	if (x>=n){x-=n;continue;}
                   	if (y<0){y+=n;continue;}
                   	continue;
                   }
                   break;
                 }

                 //将当前的count值赋给选出的空位
                      matrix[x][y]= count;
                      break;
         }
       }

       public static void print()
       {
        	for(int i = 0; i < n; i++)
        	{
        		for(int j = 0; j < n; j++)
        	    {
        			//System.out.println(matrix[i][j]);
        			System.out.print(matrix[i][j]);
        			System.out.print("_");
        	    }
        		System.out.println();
        	}
       }

       public  static void main(String[] args)
       {   //手工输入n的值，并确保为奇数
             n = 11;
           magic_squre_odd_generate();
           print();
       }
}

